import itertools

def calculate_autocorrelation_sum(seq):
    n = len(seq)
    sum_sq_c = 0
    for k in range(1, n):
        c_k = 0
        for i in range(n - k):
            c_k += seq[i] * seq[i+k]
        sum_sq_c += c_k**2
    return sum_sq_c

def find_sequence():
    for seq in itertools.product([-1, 1], repeat=16):
        if calculate_autocorrelation_sum(seq) <= 37:
            return list(seq)
    return None

result = find_sequence()
print(result)
